  5	use Illuminate\Contracts\Queue\ShouldQueue;
  6	use Illuminate\Foundation\Queue\Queueable;
  7	use Illuminate\Support\Facades\Cache;
  8	use Illuminate\Support\Facades\DB;
  9	use Illuminate\Support\Facades\Log;
 10	use Illuminate\Support\Str;
 11	use Modules\AI\Actions\ExecuteAiIntentAction;
 12	use Modules\AI\Actions\ResolveAiAdmissionAction;
 13	use Modules\AI\Contracts\RunAiSession;
 14	use Modules\AI\Enums\AiActionReceiptResultKey;
 15	use Modules\AI\Enums\AiQueueActionReason;
 16	use Modules\AI\Enums\AiQueueName;
 17	use Modules\AI\Enums\AiReceiptState;
 18	use Modules\AI\Enums\AiWorkKind;
 19	use Modules\AI\Enums\AiWorkState;
 20	use Modules\AI\Domain\Routine\SessionPlanner;
 21	use Modules\AI\Models\AiActionReceipt;
 22	use Modules\AI\Models\AiProfile;
 23	use Modules\AI\Models\AiSchedule;
 24	use Modules\AI\Models\AiWorkItem;
 25	use OGame\Models\Planet;
 26	use Throwable;
 27	
 28	class ProcessAiWork implements ShouldQueue
 29	{
 30	    use Queueable;
 31	
 32	    public int $tries = 3;
 33	
 34	    /** Bounds a poison work item; retryLease() owns the work-item attempt cap. */
 35	    public int $maxExceptions = 3;
 36	
 37	    /**
 38	     * Leave margin below the module's Horizon timeout so a worker is not force-killed
 39	     * mid-decision. The grand run raises both values for hybrid driver contention.
 40	     */
 41	    public int $timeout;
 42	
 43	    private const PAYLOAD_PLANET_ID = 'planet_id';
 44	
 45	    public function __construct(public int $workItemId)
 46	    {
 47	        $this->timeout = max(1, (int) config('ai.horizon.supervisors.supervisor-ai.timeout', 30) - 5);
 48	
 49	        // Deterministic AI work has its own module-owned Horizon lane so AI volume
 50	        // cannot starve the general or fleet lanes.
 51	        $this->onQueue(AiQueueName::Ai->value);
 52	    }
 53	
 54	    /** @return list<string> */
 55	    public function tags(): array
 56	    {
 57	        return ['ai', 'ai:work', 'ai:work-item:' . $this->workItemId];
 58	    }
 59	
 60	    public function failed(Throwable $exception): void
 61	    {
 62	        Log::error('AI work item failed after all queue attempts', [
 63	            'work_item_id' => $this->workItemId,
 64	            'error' => $exception->getMessage(),
 65	        ]);
 66	
 67	        $this->scheduleSessionRecovery();
 68	    }
 69	
 70	    public function handle(): void
 71	    {
 72	        // A switch that is off stops new decisions without discarding the work: the item stays
 73	        // pending and the first pass after it is switched back on picks it up again.
 74	        if (!app(ResolveAiAdmissionAction::class)->forWorkItem()->allowed) {
 75	            return;
 76	        }
 77	
 78	        $leaseToken = (string) Str::uuid();
 79	        // Claim before side effects. Every terminal update checks this token so
 80	        // a slow worker cannot complete work leased again by another worker.
 81	        $workItem = $this->claimDueWork($leaseToken);
 82	
 83	        if ($workItem === null) {
 84	            return;
 85	        }
 86	
 87	        $lock = Cache::lock('ai:player:' . $workItem->player_id, 300);
 88	        if (!$lock->get()) {
 89	            $this->retryContendedLease($workItem, $leaseToken);
 90	
 91	            return;
 92	        }
 93	
 94	        try {
 95	            $profile = AiProfile::query()->where('player_id', $workItem->player_id)->where('enabled', true)->first();
 96	            if ($profile === null) {
 97	                $this->completeLease($workItem, $leaseToken);
 98	
 99	                return;
100	            }
101	
102	            if ($workItem->kind === AiWorkKind::RunSession) {
103	                $this->runClaimedSession($profile, $workItem, $leaseToken);
104	
105	                return;
106	            }
107	
108	            $this->queueClaimedIntent($profile, $workItem, $leaseToken);
109	        } catch (Throwable $exception) {
110	            $this->retryLease($workItem, $leaseToken);
111	
112	            throw $exception;
113	        } finally {
114	            $lock->release();
115	        }
116	    }
117	
118	    private function claimDueWork(string $leaseToken): AiWorkItem|null
119	    {
120	        return DB::transaction(function () use ($leaseToken): AiWorkItem|null {
121	            /** @var AiWorkItem|null $workItem */
122	            $workItem = AiWorkItem::query()->lockForUpdate()->find($this->workItemId);
123	            if ($workItem === null || !$this->isClaimable($workItem) || !$this->dueForAccount($workItem)) {
124	                return null;
125	            }
126	
127	            $workItem->update([
128	                'state' => AiWorkState::Leased,
129	                'lease_token' => $leaseToken,
130	                'lease_until' => now()->addMinutes(5),
131	                'attempts' => $workItem->attempts + 1,
132	            ]);
133	
134	            return $workItem->fresh();
135	        });
136	    }
137	
138	    private function acceleratedSession(AiWorkItem $workItem): bool
139	    {
140	        if ($workItem->kind !== AiWorkKind::RunSession || (int) config('ai.population.session_interval_seconds', 0) <= 0) {
141	            return false;
142	        }
143	
144	        // Acceleration shortens the waits, not the night: a dark-period session keeps its due time.
145	        $profile = $this->workProfile($workItem);
146	
147	        return $profile === null || app(SessionPlanner::class)->isAwake($profile, now()->toImmutable());
148	    }
149	
150	    /**
151	     * Whether the account's own clock has come for this item.
152	     *
153	     * An accelerated session is claimable the moment its account is awake (that is what shortens the
154	     * waits), and any item is claimable once its own due time has passed. A session is the exception:
155	     * the one a session leaves behind is due seconds later, so a worker that is minutes behind finds
156	     * every session in the cohort overdue, and an overdue session used to be claimable at any hour --
157	     * which put the whole population online through its own night (AUTH_UPTIME). A session therefore
158	     * keeps the hour it was scheduled for: only the night session the routine placed in the dark
159	     * period itself, the reaction wake to an attack landing then, is run at night.
160	     */
161	    private function dueForAccount(AiWorkItem $workItem): bool
162	    {
163	        if ($workItem->due_at->isFuture()) {
164	            return $this->acceleratedSession($workItem);
165	        }
166	
167	        return $workItem->kind !== AiWorkKind::RunSession || $this->sessionKeepsItsOwnHour($workItem);
168	    }
169	
170	    /**
171	     * A session scheduled inside the account's waking window waits for its waking day however late the
172	     * worker is; one scheduled inside the dark period is a wake the routine meant to take.
173	     */
174	    private function sessionKeepsItsOwnHour(AiWorkItem $workItem): bool
175	    {
176	        $profile = $this->workProfile($workItem);
177	        if ($profile === null) {
178	            return true;
179	        }
180	
181	        $planner = app(SessionPlanner::class);
182	
183	        return $planner->isAwake($profile, now()->toImmutable()) || !$planner->isAwake($profile, $workItem->due_at->toImmutable());
184	    }
185	
186	    private function workProfile(AiWorkItem $workItem): AiProfile|null
187	    {
188	        return AiProfile::query()->where('player_id', $workItem->player_id)->first();
189	    }
190	
191	    private function isClaimable(AiWorkItem $workItem): bool
192	    {
193	        if (in_array($workItem->state, [AiWorkState::Pending, AiWorkState::Retry], true)) {
194	            return true;
195	        }
196	
197	        // A worker killed mid-handle leaves the item Leased; reclaim it once the lease
198	        // expires so a queue retry or the scheduler can finish the work instead of the
199	        // item staying stuck forever.
200	        return $workItem->state === AiWorkState::Leased
201	            && $workItem->lease_until !== null
202	            && $workItem->lease_until->isPast();
203	    }
204	
205	    private function runClaimedSession(AiProfile $profile, AiWorkItem $workItem, string $leaseToken): void
206	    {
207	        app(RunAiSession::class)->handle($profile, $workItem);
208	        $this->completeLease($workItem, $leaseToken);
209	    }
210	
211	    private function queueClaimedIntent(AiProfile $profile, AiWorkItem $workItem, string $leaseToken): void
212	    {
213	        // The action cap bounds what a session may touch, not what it may think: at zero the
214	        // session already decided and scheduled, so this pass closes its lease and acts on
215	        // nothing.
216	        if (!app(ResolveAiAdmissionAction::class)->forAction()->allowed) {
217	            $this->completeLease($workItem, $leaseToken);
218	
219	            return;
220	        }
221	
222	        $receipt = AiActionReceipt::query()->firstOrCreate(
223	            ['idempotency_key' => $workItem->idempotency_key],
224	            [
225	                'player_id' => $workItem->player_id,
226	                'action_type' => $workItem->kind->actionType(),
227	                'state' => AiReceiptState::Processing,
228	            ],
229	        );
230	        if (in_array($receipt->state, [AiReceiptState::Accepted, AiReceiptState::Completed, AiReceiptState::Rejected], true)) {
231	            $this->completeLease($workItem, $leaseToken);
232	
233	            return;
234	        }
235	
236	        $planetId = $this->ownedPlanetIdFor($workItem);
237	        if ($planetId === 0) {
238	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::NoOwnedPlanet->value]]);
239	            $this->completeLease($workItem, $leaseToken);
240	
241	            return;
242	        }
243	
244	        // An intent that names a body this account does not own is not this account's to act on, and
245	        // re-planning it onto a different one would silently change what the session decided.
246	        if (!Planet::query()->whereKey($planetId)->where('user_id', $workItem->player_id)->exists()) {
247	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::PlanetNotOwned->value]]);
248	            $this->completeLease($workItem, $leaseToken);
249	
250	            return;
251	        }
252	
253	        [$result, $decision, $actedPlanetId] = app(ExecuteAiIntentAction::class)->execute($workItem, $planetId);
254	        if ($result === null) {
255	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::NothingQueueable->value]]);
256	            $this->completeLease($workItem, $leaseToken);
257	
258	            return;
259	        }
260	
261	        $receipt->update([
262	            'state' => $result->successful ? AiReceiptState::Accepted : AiReceiptState::Rejected,
263	            'result' => [
264	                AiActionReceiptResultKey::QueueId->value => $result->queueId,
265	                AiActionReceiptResultKey::Reason->value => $result->reason,
266	                AiActionReceiptResultKey::Decision->value => $decision,
267	                AiActionReceiptResultKey::PlanetId->value => $actedPlanetId,
268	            ],
269	        ]);
270	        $this->completeLease($workItem, $leaseToken);
271	    }
272	
273	    private function ownedPlanetIdFor(AiWorkItem $workItem): int
274	    {
275	        return (int) ($workItem->payload[self::PAYLOAD_PLANET_ID] ?? Planet::query()->where('user_id', $workItem->player_id)->value('id'));
276	    }
277	
278	    private function completeLease(AiWorkItem $workItem, string $leaseToken): void
279	    {
280	        AiWorkItem::query()->whereKey($workItem->id)->where('lease_token', $leaseToken)->update([
281	            'state' => AiWorkState::Completed, 'lease_token' => null, 'lease_until' => null,
282	        ]);
283	    }
284	
285	    private function retryLease(AiWorkItem $workItem, string $leaseToken): void
286	    {
287	        $failed = $workItem->attempts >= $this->tries;
288	
289	        AiWorkItem::query()->whereKey($workItem->id)->where('lease_token', $leaseToken)->update([
290	            'state' => $failed ? AiWorkState::Failed : AiWorkState::Retry,
291	            'due_at' => now()->addMinute(),
292	            'lease_token' => null,
293	            'lease_until' => null,
294	        ]);
295	
296	        if ($failed) {
297	            $this->scheduleSessionRecovery();
298	        }
299	    }
300	
301	    private function retryContendedLease(AiWorkItem $workItem, string $leaseToken): void
302	    {
303	        AiWorkItem::query()->whereKey($workItem->id)->where('lease_token', $leaseToken)->update([
304	            'state' => AiWorkState::Retry,
305	            'due_at' => now()->addSeconds(5),
306	            'attempts' => 0,
307	            'lease_token' => null,
308	            'lease_until' => null,
309	        ]);
310	    }
311	
312	    private function scheduleSessionRecovery(): void
313	    {
314	        DB::transaction(function (): void {
315	            $workItem = AiWorkItem::query()
316	                ->lockForUpdate()
317	                ->find($this->workItemId);
318	
319	            if ($workItem === null || $workItem->kind !== AiWorkKind::RunSession || $workItem->state !== AiWorkState::Failed) {
320	                return;
321	            }
322	
323	            $schedule = AiSchedule::query()
324	                ->where('player_id', $workItem->player_id)
325	                ->lockForUpdate()
326	                ->first();
327	
328	            if ($schedule === null) {
329	                return;
330	            }
331	
332	            if ($schedule->generation > (int) $workItem->schedule_generation) {
333	                return;
334	            }
335	
336	            $nextGeneration = max($schedule->generation, (int) $workItem->schedule_generation) + 1;
337	            $nextDueAt = now()->addMinute();
338	
339	            // A failed session is retried a minute on only while the account is awake: a retry in the
340	            // dark period would put the account on at an hour it sleeps (AUTH_UPTIME), so it takes the
341	            // routine's next wake instead. An accelerated cohort keeps the minute: a failure there would
342	            // otherwise park the account for hours, and failures are rare enough not to fill the night.
343	            $profile = AiProfile::query()->where('player_id', $workItem->player_id)->first();
344	            if ((int) config('ai.population.session_interval_seconds', 0) <= 0 && $profile !== null && !app(SessionPlanner::class)->isAwake($profile, $nextDueAt->toImmutable())) {
345	                $nextDueAt = app(SessionPlanner::class)->plan($profile, now()->toImmutable(), $schedule->generation)->nextDueAt;
346	            }
347	
348	            $schedule->update([
349	                'next_due_at' => $nextDueAt,
350	                'generation' => $nextGeneration,
351	            ]);
352	
353	            AiWorkItem::query()->firstOrCreate(
354	                ['idempotency_key' => 'session:' . $workItem->player_id . ':' . $nextGeneration],
355	                [
356	                    'player_id' => $workItem->player_id,
357	                    'kind' => AiWorkKind::RunSession,
358	                    'due_at' => $nextDueAt,
359	                    'schedule_generation' => $nextGeneration,
360	                    'state' => AiWorkState::Pending,
361	                ],
362	            );
363	        });
364	    }
365	}

