  7	use Modules\AI\Support\RandomSource;
  8	
  9	/**
 10	 * Places each session inside the account's own waking day.
 11	 *
 12	 * The host flags a player whose fleet departures span eighteen or more distinct
 13	 * hours of the day (`ServerAdministrationController`, round-the-clock signal),
 14	 * so the routine needs a dark period the account never acts in. Every account
 15	 * keeps a nine-hour core dark period, long enough to block eight whole hours of
 16	 * every day whatever its clock offset, and each day's drift can only extend it:
 17	 * bed and wake times move the way a person's do, and the guarantee never
 18	 * shrinks (H1, H5).
 19	 */
 20	class SessionPlanner
 21	{
 22	    private const DAY_MINUTES = 1440;
 23	
 24	    /** The dark period every account keeps, whatever its wake time. */
 25	    private const CORE_DARK_MINUTES = 540;
 26	
 27	    /** Early bird to night owl: the span the account's wake time is drawn from. */
 28	    private const EARLIEST_WAKE_MINUTE = 330;
 29	
 30	    private const WAKE_SPREAD_MINUTES = 240;
 31	
 32	    /** How far one day's bed and wake time may slip past the account's core. */
 33	    private const DRIFT_MINUTES = 30;
 34	
 35	    /** Weibull shape below one: most waits are short and a few are long. */
 36	    private const TAIL_SHAPE = 0.8;
 37	
 38	    /** The mean of that shape, so a wait's own average is the wait it was given. */
 39	    private const TAIL_MEAN = 1.133;
 40	
 41	    /** Keeps the drawn unit away from zero, where its logarithm diverges. */
 42	    private const MINIMUM_UNIT = 1.0E-9;
 43	
 44	    /*
 45	     * Absences (H3). The plan states the bands per month, per quarter and per
 46	     * year, so they arrive here as per-day rates: one to three single days a
 47	     * month is about two days in thirty, one three-to-seven-day gap a quarter is
 48	     * one night in ninety, and one gap of a week or more a year is one in three
 49	     * hundred and sixty-five. Nothing reaches four weeks, which is where
 50	     * neighbours write an account off.
 51	     */
 52	    private const YEARLY_ABSENCE_RATE = 0.0027;
 53	
 54	    private const QUARTERLY_ABSENCE_RATE = 0.0137;
 55	
 56	    private const MONTHLY_ABSENCE_RATE = 0.0807;
 57	
 58	    /** Days added to the three-day gap and to the week-long one. */
 59	    private const MID_ABSENCE_SPREAD_DAYS = 3;
 60	
 61	    private const LONG_ABSENCE_SPREAD_DAYS = 3;
 62	
 63	    public function __construct(private RandomSource $randomSource)
 64	    {
 65	    }
 66	
 67	    public function plan(AiProfile $profile, CarbonImmutable $now, int $generation): SessionPlan
 68	    {
 69	        $routine = RoutineProfile::fromAiProfile($profile);
 70	        $local = $now->setTimezone($routine->timezone);
 71	        [$wake, $bed] = $this->wakingWindow($profile, $local);
 72	        $wakingMinutes = (int) $wake->diffInMinutes($bed);
 73	        $step = max($routine->sessionMinutes + 1, intdiv($wakingMinutes, $routine->sessionsPerDay));
 74	        $waitBase = max(1, $step - $routine->sessionMinutes);
 75	
 76	        // A wait skips the dark period rather than the day: one unlucky draw
 77	        // must not park the account for a week and read as abandoned.
 78	        $sessionEndsAt = $this->earliest(
 79	            $local->addMinutes($this->wait($profile, $routine->sessionMinutes, 'length:' . $generation)),
 80	            $bed,
 81	        );
 82	        $wait = min($this->wait($profile, $waitBase, 'wait:' . $generation), $wakingMinutes);
 83	        $candidate = $sessionEndsAt->addMinutes($wait);
 84	        [$wake, $bed] = $this->wakingWindow($profile, $candidate);
 85	        $nextDueAt = $candidate;
 86	
 87	        // The account looks in again when it wakes up, so the wait that ran into
 88	        // the dark period is spent: reusing it would skip the day it just woke
 89	        // into, and an absence nobody planned reads as an abandoned account.
 90	        if ($candidate->lessThan($wake)) {
 91	            [$wake, $bed] = $this->wakingAfterAbsence($profile, $wake);
 92	            $nextDueAt = $this->firstSessionOf($wake, $bed, min($this->wait($profile, $waitBase, 'wake:' . $generation), $step));
 93	        }
 94	
 95	        return app()->makeWith(SessionPlan::class, [
 96	            'sessionEndsAt' => $sessionEndsAt,
 97	            'nextDueAt' => $nextDueAt,
 98	        ]);
 99	    }
100	
101	    /**
102	     * Whether the instant falls inside the account's waking window, i.e. the account
103	     * would be awake then rather than in its dark period (SP3). The day's own drift
104	     * is applied, so the answer is for the window the instant actually lands in.
105	     */
106	    public function isAwake(AiProfile $profile, CarbonImmutable $instant): bool
107	    {
108	        $local = $instant->setTimezone(RoutineProfile::fromAiProfile($profile)->timezone);
109	        [$wake, $bed] = $this->dayWindow($profile, $local->startOfDay());
110	
111	        return $local->greaterThanOrEqualTo($wake) && $local->lessThan($bed);
112	    }
113	
114	    /**
115	     * The waking window that contains the moment, or the next one when the
116	     * moment falls inside a dark period.
117	     *
118	     * @return array{0: CarbonImmutable, 1: CarbonImmutable}
119	     */
120	    private function wakingWindow(AiProfile $profile, CarbonImmutable $local): array
121	    {
122	        $day = $local->startOfDay();
123	        [$wake, $bed] = $this->dayWindow($profile, $day);
124	
125	        // Before today's wake the account is still in the dark period the
126	        // previous day ended with, and once it reaches today's bed the window
127	        // containing it is the next day's.
128	        if ($local->lessThan($wake)) {
129	            $day = $day->subDay();
130	            [$wake, $bed] = $this->dayWindow($profile, $day);
131	        }
132	
133	        if ($local->greaterThanOrEqualTo($bed)) {
134	            $day = $day->addDay();
135	            [$wake, $bed] = $this->dayWindow($profile, $day);
136	        }
137	
138	        return [$wake, $bed];
139	    }
140	
141	    /** @return array{0: CarbonImmutable, 1: CarbonImmutable} */
142	    private function dayWindow(AiProfile $profile, CarbonImmutable $day): array
143	    {
144	        $wakeMinute = $this->coreWakeMinute($profile) + $this->drift($profile, $day, 'wake');
145	        $bedMinute = $wakeMinute + self::DAY_MINUTES - self::CORE_DARK_MINUTES - $this->drift($profile, $day, 'bed');
146	
147	        return [$day->addMinutes($wakeMinute), $day->addMinutes($bedMinute)];
148	    }
149	
150	    /** The first session of a waking day: after waking, but never past its bed. */
151	    private function firstSessionOf(CarbonImmutable $wake, CarbonImmutable $bed, int $wait): CarbonImmutable
152	    {
153	        $start = $wake->addMinutes($wait);
154	
155	        return $start->lessThan($bed) ? $start : $bed->subMinute();
156	    }
157	
158	    /**
159	     * The day the account comes back to, which is not always the next one.
160	     *
161	     * @return array{0: CarbonImmutable, 1: CarbonImmutable}
162	     */
163	    private function wakingAfterAbsence(AiProfile $profile, CarbonImmutable $wake): array
164	    {
165	        return $this->wakingWindow($profile, $wake->addDays($this->absenceDays($profile, $wake)));
166	    }
167	
168	    /**
169	     * How many waking days the account is away for, decided once a night.
170	     *
171	     * A night away is a person's ordinary absence; a few days away is a trip;
172	     * a week or more is the holiday that also sets the host's inactive marker,
173	     * which humans do set.
174	     */
175	    private function absenceDays(AiProfile $profile, CarbonImmutable $day): int
176	    {
177	        $date = $day->toDateString();
178	        $unit = $this->randomSource->unitInterval($profile->random_seed, 'routine:absence:' . $date);
179	
180	        return match (true) {
181	            $unit < self::YEARLY_ABSENCE_RATE => 7 + $this->scaled($profile, 'routine:away-long:' . $date, self::LONG_ABSENCE_SPREAD_DAYS),
182	            $unit < self::QUARTERLY_ABSENCE_RATE => 3 + $this->scaled($profile, 'routine:away-mid:' . $date, self::MID_ABSENCE_SPREAD_DAYS),
183	            $unit < self::MONTHLY_ABSENCE_RATE => 1,
184	            default => 0,
185	        };
186	    }
187	
188	    private function coreWakeMinute(AiProfile $profile): int
189	    {
190	        return self::EARLIEST_WAKE_MINUTE + $this->scaled($profile, 'routine:anchor', self::WAKE_SPREAD_MINUTES);
191	    }
192	
193	    /** How far this day's bed or wake time slips past the account's core. */
194	    private function drift(AiProfile $profile, CarbonImmutable $day, string $edge): int
195	    {
196	        return $this->scaled($profile, 'routine:' . $edge . ':' . $day->toDateString(), self::DRIFT_MINUTES);
197	    }
198	
199	    /**
200	     * A Weibull draw, whose shape below one gives the heavy tail human activity
201	     * has: many short waits and the occasional long one. Jitter on a fixed
202	     * period would leave the period itself readable (H2, H5).
203	     */
204	    private function wait(AiProfile $profile, int $base, string $context): int
205	    {
206	        $unit = max($this->randomSource->unitInterval($profile->random_seed, $context), self::MINIMUM_UNIT);
207	        $drawn = ($base / self::TAIL_MEAN) * (-log($unit)) ** (1 / self::TAIL_SHAPE);
208	
209	        // Never zero: the account does not run two sessions in the same minute.
210	        return max(1, (int) round($drawn));
211	    }
212	
213	    private function scaled(AiProfile $profile, string $context, int $ceiling): int
214	    {
215	        return (int) round($this->randomSource->unitInterval($profile->random_seed, $context) * $ceiling);
216	    }
217	
218	    private function earliest(CarbonImmutable $first, CarbonImmutable $second): CarbonImmutable
219	    {
220	        return $first->lessThan($second) ? $first : $second;
221	    }
222	}

