 21	 *
 22	 * The game is calculation over timestamps, so this command owns the clock: it freezes Carbon at an
 23	 * instant, runs everything that is due at that instant (fleet arrivals, the module's due work, the
 24	 * once-a-while maintenance commands the scheduler would fire), then jumps straight to the next instant
 25	 * anything is due. A quiet night costs one jump, not eight hours. The routines, waking windows and
 26	 * night rest stay real, because the sessions read the simulated clock; nothing is accelerated or
 27	 * bypassed, which is the difference from `ai.population.session_interval_seconds`.
 28	 *
 29	 * DEV TOOLING, write-heavy: it moves a database into the future, so it only runs on a database whose
 30	 * name says it is a simulation copy (`ogamex-sim...`), never on the live cohort. `bash scripts/ogamex
 31	 * sim` clones the cohort into one, runs this and reads the scorecard and invariants back at the
 32	 * simulated instant.
 33	 */
 34	#[Description('Advance simulated game time and play the AI cohort through it without waiting.')]
 35	#[Signature('ai:sim
 36	    {--hours=24 : Simulated hours to play}
 37	    {--from= : Start instant (default: where the last run on this database stopped, else the real now)}
 38	    {--accounts= : Play only the first N enabled accounts}
 39	    {--max-step=900 : Longest jump in simulated seconds when nothing is due}
 40	    {--maintenance=900 : Simulated seconds between campaign, alliance and score-sample passes}
 41	    {--highscore-every=3600 : Simulated seconds between the three highscore generators (each walks every player; the real schedule runs them every 300 s)}
 42	    {--max-wall= : Stop after this many real seconds and keep the state, so a later run continues}
 43	    {--native-cognition : Opt-in only: skip the Fatima/CBRKit/AgentOS sidecars and the language lane and play on the native engines}
 44	    {--workers=1 : Fork this many processes per simulated instant, each running a share of the due sessions against the sidecars at the same time}
 45	    {--keep-accelerated : Keep ai.population.session_interval_seconds instead of playing real routines}
 46	    {--max-errors=300 : Abort when this many errors pile up with no session having run (a broken build, not a result)}
 47	    {--force-db : Allow a database whose name does not contain "sim"}')]
 48	class SimulateAiTime extends Command
 49	{
 50	    private const PASSES_PER_INSTANT = 40;
 51	
 52	    private const BATCH = 500;
 53	
 54	    /** @var array<string, int> */
 55	    private array $errors = [];
 56	
 57	    /** @var array<string, array{0: float, 1: int}> seconds and calls per phase, printed as PROFILE at the end */
