 62	    public function handle(): int
 63	    {
 64	        $database = (string) DB::connection()->getDatabaseName();
 65	
 66	        if (!str_contains(strtolower($database), 'sim') && !$this->option('force-db')) {
 67	            $this->error("Refusing to move [{$database}] into the future: the name must contain \"sim\" (or pass --force-db).");
 68	
 69	            return self::FAILURE;
 70	        }
 71	
 72	        config(['queue.default' => 'sync']);
 73	        if ($this->option('native-cognition')) {
 74	            config([
 75	                'ai.cognition.mode' => 'native',
 76	                'ai.cognition.memory.driver' => 'native',
 77	                'ai.cognition.experience.driver' => 'native',
 78	                'ai.cognition.conversation.enabled' => false,
 79	                'ai.language.enabled' => false,
 80	            ]);
 81	            Http::preventStrayRequests();
 82	        }
 83	        if (!$this->option('native-cognition')) {
 84	            $this->probeSidecars();
 85	        }
 86	        if (!$this->option('keep-accelerated')) {
 87	            config(['ai.population.session_interval_seconds' => 0]);
 88	        }
 89	
 90	        SimulatedTime::release();
 91	        $stateFile = storage_path('app/ai-sim/' . preg_replace('/[^A-Za-z0-9_.-]/', '_', $database) . '.txt');
 92	        $start = $this->startInstant($stateFile);
 93	        $end = $start->addSeconds((int) round((float) $this->option('hours') * 3600));
 94	        $players = $this->players();
 95	
 96	        if ($players === []) {
 97	            $this->error('No enabled AI account in this database.');
 98	
 99	            return self::FAILURE;
100	        }
101	
102	        $this->info(sprintf('SIM: %s -> %s (%.1f h), %d account(s), database %s', $start->toIso8601String(), $end->toIso8601String(), $start->floatDiffInHours($end), count($players), $database));
103	
104	        $wallStart = microtime(true);
105	        $wallLimit = $this->option('max-wall') === null ? null : (float) $this->option('max-wall');
106	        $maintenanceEvery = max(60, (int) $this->option('maintenance'));
107	        $maxStep = max(1, (int) $this->option('max-step'));
108	        $now = $start;
109	        $nextMaintenance = $start;
110	        $hourIndex = -1;
111	        $hour = ['sessions' => 0, 'other' => 0, 'errors' => 0];
112	        $total = ['sessions' => 0, 'other' => 0, 'errors' => 0];
113	        $stoppedEarly = false;
114	        $jumps = 0;
115	
116	        while ($now->lessThan($end)) {
117	            SimulatedTime::freezeAt($now);
118	
119	            // One commit per simulated instant instead of one per statement group: every session and order
120	            // writes dozens of rows, and each commit is an fsync. Inner transactions become savepoints.
121	            $drain = function () use ($players): array {
122	                $this->timed('fleet arrivals', fn () => $this->runFleetArrivals());
123	
124	                return $this->timed('due work (all sessions and orders)', fn (): array => $this->drainDueWork($players));
125	            };
126	            // Forked workers each need their own connection, so the one-commit-per-instant wrapper only applies to a single process.
127	            $ran = $this->workerCount() > 1 ? $drain() : DB::transaction($drain);
128	            foreach ($ran as $key => $count) {
129	                $hour[$key] += $count;
130	                $total[$key] += $count;
131	            }
132	
133	            if ($now->greaterThanOrEqualTo($nextMaintenance)) {
134	                $this->runMaintenance($now);
135	                $nextMaintenance = $now->addSeconds($maintenanceEvery);
136	            }
137	
138	            $currentHour = (int) floor($start->diffInSeconds($now) / 3600);
139	            if ($currentHour !== $hourIndex) {
140	                if ($hourIndex >= 0) {
141	                    $this->reportHour($start->addHours($hourIndex), $hour);
142	                }
143	                $hourIndex = $currentHour;
144	                $hour = ['sessions' => 0, 'other' => 0, 'errors' => 0];
145	            }
146	
147	            if ($total['errors'] >= max(1, (int) $this->option('max-errors')) && $total['sessions'] === 0) {
148	                $this->error('SIM ABORTED: ' . $total['errors'] . ' errors and no session has run -- the build is broken, the numbers would mean nothing.');
149	                $this->reportErrors();
150	
151	                return self::FAILURE;
152	            }
153	
154	            if ($wallLimit !== null && microtime(true) - $wallStart > $wallLimit) {
155	                $stoppedEarly = true;
156	
157	                break;
158	            }
159	
160	            $now = $this->timed('next-instant queries', fn (): CarbonImmutable => $this->nextInstant($now, $end, $nextMaintenance, $players, $maxStep));
161	            $jumps++;
162	        }
163	
164	        if ($hourIndex >= 0) {
165	            $this->reportHour($start->addHours($hourIndex), $hour);
166	        }
167	
168	        $stoppedAt = $stoppedEarly ? $now : $end;
169	        SimulatedTime::freezeAt($stoppedAt);
170	        @mkdir(dirname($stateFile), 0775, true);
171	        file_put_contents($stateFile, $stoppedAt->toIso8601String());
172	
173	        $this->reportErrors();
174	        $this->line(sprintf('JUMPS: %d (average %.0f simulated seconds per jump)', $jumps, $start->diffInSeconds($stoppedAt) / max(1, $jumps)));
175	        $this->reportProfile();
176	        $wall = max(0.001, microtime(true) - $wallStart);
177	        $simulated = $start->diffInSeconds($stoppedAt);
178	        $this->info(sprintf(
179	            'SIM_NOW: %s',
180	            $stoppedAt->toIso8601String(),
181	        ));
182	        $this->info(sprintf(
183	            'SIM: %s h played in %.0f s (x%.0f), %d session(s), %d other work item(s), %d error(s)%s',
184	            number_format($simulated / 3600, 1),
185	            $wall,
186	            $simulated / $wall,
187	            $total['sessions'],
188	            $total['other'],
189	            $total['errors'],
190	            $stoppedEarly ? ' -- stopped at --max-wall, run again to continue' : '',
191	        ));
192	
193	        return self::SUCCESS;
194	    }
