196	    /** @template T @param callable(): T $work @return T */
197	    private function timed(string $phase, callable $work): mixed
198	    {
199	        $started = microtime(true);
200	
201	        try {
202	            return $work();
203	        } finally {
204	            $this->profile[$phase] ??= [0.0, 0];
205	            $this->profile[$phase][0] += microtime(true) - $started;
206	            $this->profile[$phase][1]++;
