290	    /**
291	     * Run every work item due at the frozen instant, orders before sessions, and repeat because a
292	     * session can make more work due now. Returns what ran, split into sessions and other work.
293	     *
294	     * @param list<int> $players
295	     * @return array{sessions: int, other: int, errors: int}
296	     */
297	    private function drainDueWork(array $players): array
298	    {
299	        $ran = ['sessions' => 0, 'other' => 0, 'errors' => 0];
300	        $attempted = [];
301	
302	        for ($pass = 0; $pass < self::PASSES_PER_INSTANT; $pass++) {
303	            $due = $this->dueQuery($players)
304	                ->orderByRaw('kind = ? asc', [AiWorkKind::RunSession->value])
305	                ->orderBy('due_at')
306	                ->limit(self::BATCH)
307	                ->get(['id', 'kind'])
308	                ->reject(fn (object $row): bool => isset($attempted[$row->id]));
309	
310	            if ($due->isEmpty()) {
311	                break;
312	            }
313	
314	            foreach ($due as $row) {
315	                $attempted[$row->id] = true;
316	            }
317	
318	            foreach ($this->runRows($due->values()->all()) as $key => $count) {
319	                $ran[$key] += $count;
320	            }
321	        }
322	
323	        return $ran;
324	    }
