326	    private function workerCount(): int
327	    {
328	        $workers = max(1, (int) $this->option('workers'));
329	
330	        if ($workers > 1 && !function_exists('pcntl_fork')) {
331	            return 1;
332	        }
333	
334	        return $workers;
