337	    /**
338	     * Run the due rows: in this process, or split across forked workers that all stand at the same simulated
339	     * instant. A session spends most of its wall time waiting on the sidecars, so concurrent sessions overlap
340	     * those waits. Sessions of different accounts already run concurrently in production.
341	     *
342	     * @param list<object> $rows
343	     * @return array{sessions: int, other: int, errors: int}
344	     */
345	    private function runRows(array $rows): array
346	    {
347	        $workers = $this->workerCount();
348	
349	        if ($workers <= 1 || count($rows) < $workers * 2) {
350	            return $this->processRows($rows);
351	        }
352	
353	        // No open connection may cross the fork: a child closing a shared socket would cut the parent's session.
354	        DB::purge();
355	        $directory = sys_get_temp_dir() . '/ai-sim-' . getmypid() . '-' . bin2hex(random_bytes(3));
356	        @mkdir($directory);
357	        $children = [];
358	
359	        foreach (range(0, $workers - 1) as $index) {
360	            $share = array_values(array_filter($rows, fn (int $position): bool => $position % $workers === $index, ARRAY_FILTER_USE_KEY));
361	            $pid = pcntl_fork();
362	
363	            if ($pid === 0) {
364	                $this->errors = [];
365	                $result = $this->processRows($share);
366	                file_put_contents("{$directory}/{$index}.json", json_encode(['ran' => $result, 'errors' => $this->errors]));
367	                DB::purge();
368	
369	                exit(0);
370	            }
371	
372	            $children[$index] = $pid;
373	        }
374	
375	        $total = ['sessions' => 0, 'other' => 0, 'errors' => 0];
376	        foreach ($children as $index => $pid) {
377	            pcntl_waitpid($pid, $status);
378	            $file = "{$directory}/{$index}.json";
379	            $report = is_file($file) ? json_decode((string) file_get_contents($file), true) : null;
380	
381	            if (!is_array($report)) {
382	                $total['errors']++;
383	                $this->noteError("worker {$index} died without a report (status {$status})");
384	
385	                continue;
386	            }
387	
388	            foreach ($report['ran'] as $key => $count) {
389	                $total[$key] += $count;
390	            }
391	            foreach ($report['errors'] as $message => $count) {
392	                $this->errors[$message] = ($this->errors[$message] ?? 0) + $count;
393	            }
394	            @unlink($file);
395	        }
396	        @rmdir($directory);
397	
398	        return $total;
399	    }
