401	    /**
402	     * @param list<object> $rows
403	     * @return array{sessions: int, other: int, errors: int}
404	     */
405	    private function processRows(array $rows): array
406	    {
407	        $ran = ['sessions' => 0, 'other' => 0, 'errors' => 0];
408	
409	        foreach ($rows as $row) {
410	            try {
411	                app()->makeWith(ProcessAiWork::class, ['workItemId' => (int) $row->id])->handle();
412	                $ran[(string) $row->kind === (string) AiWorkKind::RunSession->value ? 'sessions' : 'other']++;
413	            } catch (Throwable $exception) {
414	                $ran['errors']++;
415	                $this->noteError('work item: ' . $exception->getMessage());
416	            }
417	        }
418	
419	        return $ran;
420	    }
