422	    /**
423	     * Say plainly which sidecars answer before an hour of play depends on them. A sidecar that is down costs
424	     * its connect timeout on every call it is tried, which is what made sessions take seconds each.
425	     */
426	    private function probeSidecars(): void
427	    {
428	        $sidecars = [
429	            'fatima (affect)' => config('ai.cognition.fatima.base_url'),
430	            'cbrkit (experience)' => config('ai.cognition.experience.cbrkit.base_url'),
431	            'agentos (memory)' => config('ai.cognition.memory.agentos.base_url'),
432	        ];
433	
434	        foreach ($sidecars as $name => $url) {
435	            $parts = parse_url((string) $url);
436	            if (!is_array($parts) || !isset($parts['host'])) {
437	                $this->warn("SIDECAR {$name}: no base_url configured");
438	
439	                continue;
440	            }
441	
442	            $started = microtime(true);
443	            $socket = @fsockopen($parts['host'], (int) ($parts['port'] ?? 80), $errno, $error, 1.0);
444	            $took = (microtime(true) - $started) * 1000;
445	
446	            if ($socket === false) {
447	                $this->warn(sprintf('SIDECAR %s DOWN at %s (%s): every call will wait out its timeout. Start it, or the sim is slow and plays without it.', $name, $url, $error));
448	
449	                continue;
450	            }
451	
452	            fclose($socket);
453	            $this->line(sprintf('SIDECAR %s up at %s (%.0f ms to connect)', $name, $url, $took));
454	        }
455	    }
