458	    private function dueQuery(array $players): \Illuminate\Database\Query\Builder
459	    {
460	        $now = SimulatedTime::now();
461	
462	        return DB::table('ai_work_items')
463	            ->whereIn('player_id', $players)
464	            ->where(function ($query) use ($now): void {
465	                $query->where(function ($ready) use ($now): void {
466	                    $ready->whereIn('state', [AiWorkState::Pending->value, AiWorkState::Retry->value])
467	                        ->where('due_at', '<=', $now);
468	                })->orWhere(function ($stranded) use ($now): void {
