474	    /**
475	     * The next instant anything can happen: a work item coming due, a fleet landing, the next
476	     * maintenance pass, the end of the run, or `max-step` of nothing at all. Work that is already
477	     * due but was refused (a claim that will not take it) cannot stall the clock: it waits a minute.
478	     *
479	     * @param list<int> $players
480	     */
481	    private function nextInstant(CarbonImmutable $now, CarbonImmutable $end, CarbonImmutable $nextMaintenance, array $players, int $maxStep): CarbonImmutable
482	    {
483	        $candidates = [$end, $nextMaintenance, $now->addSeconds($maxStep)];
484	
485	        $nextWork = DB::table('ai_work_items')
486	            ->whereIn('player_id', $players)
487	            ->whereIn('state', [AiWorkState::Pending->value, AiWorkState::Retry->value])
488	            ->min('due_at');
489	        if ($nextWork !== null) {
490	            // Still due after the drain means the worker refused it (a claim that waits for the waking
491	            // window, an admission that is off). Retrying such an item every simulated minute made a night
492	            // of hundreds of pointless jumps, so it is looked at again in five minutes.
493	            $due = CarbonImmutable::parse($nextWork);
494	            $candidates[] = $due->greaterThan($now) ? $due : $now->addSeconds(min($maxStep, 300));
495	        }
496	
497	        $nextLease = DB::table('ai_work_items')
498	            ->whereIn('player_id', $players)
499	            ->where('state', AiWorkState::Leased->value)
500	            ->min('lease_until');
501	        if ($nextLease !== null) {
502	            $candidates[] = CarbonImmutable::parse($nextLease)->addSecond();
503	        }
504	
505	        $nextArrival = DB::table('fleet_missions')
506	            ->where('processed', 0)->where('canceled', 0)
507	            ->where('time_arrival', '>', $now->getTimestamp())
508	            ->min('time_arrival');
509	        if ($nextArrival !== null) {
510	            $candidates[] = CarbonImmutable::createFromTimestamp((int) $nextArrival);
511	        }
512	
513	        $next = collect($candidates)->sortBy(fn (CarbonImmutable $at): int => $at->getTimestamp())->first();
514	
515	        return $next->lessThanOrEqualTo($now) ? $now->addSeconds(min($maxStep, 60)) : $next;
516	    }
