26	    public static function fromAiProfile(AiProfile $profile): self
27	    {
28	        $settings = $profile->settings ?? [];
29	        $timezone = (string) ($settings[AiProfileSettings::TIMEZONE] ?? AiProfileSettings::DEFAULT_TIMEZONE);
30	
31	        try {
32	            app()->makeWith(DateTimeZone::class, ['timezone' => $timezone]);
33	        } catch (Exception) {
34	            $timezone = AiProfileSettings::DEFAULT_TIMEZONE;
35	        }
36	
37	        return app()->makeWith(self::class, [
38	            'timezone' => $timezone,
39	            'sessionMinutes' => max(self::MINIMUM_MINUTES, (int) ($settings[AiProfileSettings::SESSION_MINUTES] ?? self::DEFAULT_SESSION_MINUTES)),
40	            'sessionsPerDay' => self::sessionsPerDay($profile->activity_band, PersonaTaste::fromSeed((int) $profile->random_seed, app(RandomSource::class))->diligence),
41	        ]);
42	    }
43	
44	    /**
45	     * How often each kind of player looks at the account in a day.
46	     *
47	     * This is the player's pace, not a game rule: a casual player opens the game a
48	     * couple of times around work, and a hardcore one lives in it. The figure is the
49	     * target the waits are drawn around, not the visits a month actually
50	     * contains: the longest waits are spent asleep, so a persona lands somewhat
51	     * above its target, and the targets are set from that measurement.
52	     *
53	     * Diligence is the account's own: one miner is not the next miner, so a lazy
54	     * one plays the floor of its archetype band and a diligent one the ceiling.
55	     */
56	    private static function sessionsPerDay(AiActivityBand|null $band, float $diligence): int
57	    {
58	        [$fewest, $most] = self::presenceBand($band);
59	
60	        return $fewest + (int) round(($most - $fewest) * $diligence);
61	    }
62	
63	    /**
64	     * The visits a day each pace of player makes, from the analogue benchmark the plan records. Pace is
65	     * the account's own activity band, not its archetype, so a casual fleeter and a hardcore miner both
66	     * exist; diligence places the account inside its band. An account with no stated pace plays Regular.
67	     *
68	     * @return array{0: int, 1: int}
69	     */
70	    private static function presenceBand(AiActivityBand|null $band): array
71	    {
72	        return match ($band ?? AiActivityBand::Regular) {
73	            AiActivityBand::Casual => [1, 3],
74	            AiActivityBand::Regular => [3, 7],
75	            AiActivityBand::Active => [7, 12],
76	            AiActivityBand::Hardcore => [12, 18],
77	        };
78	    }
79	}

