14	/**
15	 * Enforces the retention the module declares, instead of only writing it down.
16	 *
17	 * Several tables record an `expires_at` for a single row's *validity* -- a trace
18	 * is no longer evidence after thirty days, a sealed reply is no longer worth
19	 * sending after three hours -- and a validity filter keeps such a row out of
20	 * every query while leaving it on disk forever. A module that runs one session
21	 * per account per hour against an unbounded population cannot leave that to the
22	 * disk, so the rows that have outlived their purpose are deleted here.
23	 *
24	 * What is deleted is bookkeeping, never the account's memory: relationships,
25	 * commitments, memory facts, emotional episodes, social exchanges and
26	 * experience cases all stay, because they are what the account knows rather
27	 * than what it happened to log. The windows are the ones the plan declares,
28	 * sized from the pilot's measured volumes against the 2 vCPU / 2 GB profile.
29	 */
30	class PruneAiRecordsAction
31	{
32	    /** @var array<class-string<Model>, int> */
33	    public const RETENTION_DAYS = [
34	        AiWorkItem::class => 90,
35	        AiActionReceipt::class => 90,
36	        AiDecisionTrace::class => 30,
37	        AiObservation::class => 30,
38	        AiConversationReply::class => 30,
39	        // The score series is not a log: it is the only record of what the accounts' points were,
40	        // because the host keeps current points and no history, so a review cannot re-derive a
41	        // window it has deleted. It is kept long enough to compare a window against the same
42	        // cohort months earlier, and it stays one row per account per hour either way.
43	        AiScoreSample::class => 400,
44	    ];
45	
46	    public function __construct(private AiClock $clock)
47	    {
48	    }
49	
50	    public function handle(): int
51	    {
52	        $now = $this->clock->now();
53	        $pruned = 0;
54	
55	        foreach (self::RETENTION_DAYS as $model => $days) {
56	            $pruned += $model::query()->where('created_at', '<', $now->subDays($days))->delete();
57	        }
58	
59	        return $pruned;
60	    }
61	}

