122	    public function __construct(
123	        private QueueableBuildingPlanner $queueableBuildingPlanner,
124	        private QueueableUnitPlanner $queueableUnitPlanner,
125	        private QueueableColonyPlanner $queueableColonyPlanner,
126	        private QueueableExpeditionPlanner $queueableExpeditionPlanner,
127	        private QueueableFleetSavePlanner $queueableFleetSavePlanner,
128	        private QueueableSpyPlanner $queueableSpyPlanner,
129	        private QueueableTransferPlanner $queueableTransferPlanner,
130	        private QueueableRecyclePlanner $queueableRecyclePlanner,
131	        private QueueableMinePercentPlanner $queueableMinePercentPlanner,
132	        private QueueablePhalanxPlanner $queueablePhalanxPlanner,
133	        private QueueableDefendPlanner $queueableDefendPlanner,
134	        private QueueableTradePlanner $queueableTradePlanner,
135	        private QueueableRelocationPlanner $queueableRelocationPlanner,
136	        private QueueableJumpGatePlanner $queueableJumpGatePlanner,
137	        private RaidPlanner $raidPlanner,
