145	    /**
146	     * Writes the one work item that carries the intent out, keyed by the session's
147	     * own id: a retried session converges on one action, a later session decides
148	     * again. The payload is whatever the plan approved, so the schedule and the
149	     * executor always name the same objective.
150	     *
151	     * @param array<string, mixed> $payload
152	     */
153	    private function enqueue(AiProfile $profile, AiWorkItem $sessionWorkItem, AiWorkKind $kind, array $payload, ?CarbonImmutable $dueAt = null, string $keySuffix = ''): void
154	    {
155	        AiWorkItem::query()->firstOrCreate(
156	            ['idempotency_key' => 'intent:session:' . $sessionWorkItem->id . $keySuffix],
157	            [
158	                'player_id' => $profile->player_id,
159	                'kind' => $kind,
160	                'due_at' => $dueAt ?? $this->clock->now(),
161	                'schedule_generation' => (int) ($sessionWorkItem->schedule_generation ?? 1),
162	                'state' => AiWorkState::Pending,
163	                'payload' => $payload,
164	            ],
165	        );
166	    }
