168	    public function handle(AiProfile $profile, AiWorkItem $sessionWorkItem, DecisionTrace $trace): void
169	    {
170	        // An account the host no longer has, or one with no planets, has nothing an intent could
171	        // be spent on: the session records what it decided and stops scheduling (L2), so the
172	        // planners are never asked to build for it. Asking them anyway built a host player for an
173	        // account that does not exist, which the host refuses.
174	        if (!$this->accountStateResolver->resolve($profile->player_id)->schedules()) {
175	            return;
176	        }
177	
178	        // Every case is listed: adding a capability means deciding here where it is executed, and
179	        // a capability with no executor must not be published to begin with.
180	        $type = $trace->selected->candidate->type;
181	        // The unit plan is read here, before the building steps are enqueued, because one order's
182	        // placement decides whether it happens at all: the first wall of a planet that stands bare
183	        // beside a walled sibling is priced against the balance those steps spend, so the host
184	        // refuses it and the planet stays naked session after session (QUAL-003).
185	        //
186	        // It is read for every chosen action, not only QueueUnits: the wall candidate is one of a
187	        // dozen and the economy's habit outranks it in most logins, so waiting for the sessions the
188	        // engine happens to pick the shipyard left the bare planet naked while the account kept
189	        // colonising (measured live 2 Oct 2026: 1 planet at zero defence beside a sibling holding
190	        // 1,746). A login is one wall order whichever action was chosen.
191	        // The wall's own facility may be refused by the economy in the same login (the planet is saving
192	        // for its next mine), so the unit plan is asked before the building steps for every chosen
193	        // action: a bare planet's wall is the one order whose placement decides whether it happens.
194	        $units = $this->queueableUnitPlanner->plan($profile->player_id);
195	        $unitsFirst = $units instanceof QueueableUnit && $units->aheadOfEconomy;
196	
197	        // The marked wall is written before the building steps, because work falls due in the order
198	        // it was written and same-instant work keeps that order: written after them, the steps have
199	        // already spent the balance the wall was priced against, the host refuses it, and the planet
200	        // stands naked beside its walled sibling again on the next login (QUAL-003).
201	        //
202	        // A wall placed on a login that chose something else keeps a key of its own, so the session's
203	        // own action still owns the primary key: a retried session converges on that action, and the
204	        // wall is one more order in the login rather than the login's objective.
205	        if ($unitsFirst) {
206	            $this->scheduleUnits($profile, $sessionWorkItem, $this->clock->now(), $units, $type === AiCandidateActionType::QueueUnits ? '' : ':wall');
207	        }
208	
209	        // Every *other* bare sibling takes its wall in the same login: a player clicks through all the
210	        // naked colonies before logging off, and the invariant reads the account, so the one order the
211	        // pass above places left the rest at zero for as many logins as the account has planets -- more
212	        // than a day of its own sessions (QUAL-003: 3 planets at zero beside one holding 1,312 units).
213	        // Each order keeps a key of its own planet, so a retried session converges on the same set.
214	        foreach ($this->queueableUnitPlanner->standingDefenceOrders($profile->player_id) as $order) {
215	            if ($unitsFirst && $units instanceof QueueableUnit && $order->planetId === $units->planetId) {
216	                continue;
217	            }
218	
219	            $this->scheduleUnits($profile, $sessionWorkItem, $this->clock->now(), $order, ':wall:planet:' . $order->planetId);
220	        }
221	
222	        // An inbound is not one order. Whichever page the login opened, the account answers it with
223	        // every response the threat planner named: the fleet that is worth the trip leaves and the
224	        // stock the raider would otherwise carry off leaves on the hulls kept at home. Each response
225	        // is placed by the planner that owns that order, and the wall among them is the unit plan
226	        // above. Written here, ahead of the building steps, because those steps spend the stock the
227	        // save and the ferry were priced against, and an inbound leaves no second login to place them.
228	        $this->scheduleThreatResponses($profile, $sessionWorkItem, $type);
229	
230	        // A player refills the build queues and the lab every login before turning to the shipyard or
231	        // the fleet; choosing a raid, a ship, nothing at all or answering an inbound fleet must not
232	        // leave a planet idle until the next session. The refill asks the planner, never the decision
233	        // trace: a planet is buildable exactly when the planner offers it a step -- the same call the
234	        // cohort read-out makes -- so asking the trace instead lets the two disagree and the account
235	        // read idle while it had a legal order to place. A planet the planner offers no step for
236	        // enqueues nothing, so a login with nothing to spend stays quiet.
237	        // A Save answers first: its intent is written ahead of these steps, so the fleet still moves
238	        // before the last order lands.
239	        // An attacked account saves before it builds: work falls due in the order it was written and
240	        // same-instant work keeps that order, so the save is written here -- ahead of the building
241	        // steps -- or the stock it moves has already been spent by them and the fleet stays on the
242	        // ground. The calm save has no such errand and takes the match arm below, after the builds.
243	        if ($type === AiCandidateActionType::FleetSave && !$this->isCalmSave($type, $trace)) {
244	            $this->scheduleFleetSave($profile, $sessionWorkItem, $this->clock->now());
245	        }
246	
247	        // A session that decided nothing is a player with no intent to spend and never refills the
248	        // queues; a session the engine offered no economy step is one with nothing legal to place.
249	        $economySteps = $this->refillsQueues($type, $trace)
250	            ? $this->fillQueues($profile, $sessionWorkItem, $this->economyKey($type))
251	            : 0;
252	
253	        match ($type) {
254	            // Build and Research are filled by the pass above under the session's own key, so the
255	            // refill and the session's objective are one work item.
256	            AiCandidateActionType::Build, AiCandidateActionType::Research => null,
257	            // The shipyard gets what the buildings leave, so its order waits until they are placed:
258	            // the host cancels a building it cannot pay for, and a ship order placed first would cause it.
259	            // A marked wall is already written above; the repeat finds that row and leaves its time.
260	            AiCandidateActionType::QueueUnits => $this->scheduleShipyard($profile, $sessionWorkItem, $this->clock->now()->addSeconds($economySteps * self::SECONDS_BETWEEN_PLANETS), $units),
261	            AiCandidateActionType::Colonize => $this->scheduleColony($profile, $sessionWorkItem),
262	            AiCandidateActionType::Expedition => $this->scheduleExpedition($profile, $sessionWorkItem),
263	            // The ferry moves stock the buildings were priced against, so it waits for them the way
264	            // the shipyard and the save do: a transfer written at the session's own instant runs
265	            // between the second and third planet's build and the host then refuses those builds,
266	            // leaving the planets idle until the next login.
267	            AiCandidateActionType::Transfer => $this->scheduleTransfer($profile, $sessionWorkItem, $this->clock->now()->addSeconds($economySteps * self::SECONDS_BETWEEN_PLANETS)),
268	            AiCandidateActionType::Recycle => $this->scheduleRecycle($profile, $sessionWorkItem),
269	            AiCandidateActionType::FleetSave => $this->scheduleFleetSave($profile, $sessionWorkItem, $this->clock->now()->addSeconds($economySteps * self::SECONDS_BETWEEN_PLANETS), '', $this->isCalmSave($type, $trace) ? $trace->perception->upcomingAbsenceMinutes : null),
270	            AiCandidateActionType::Recall => $this->scheduleRecall($profile, $sessionWorkItem),
271	            AiCandidateActionType::Spy => $this->scheduleSpy($profile, $sessionWorkItem),
272	            AiCandidateActionType::Raid => $this->scheduleRaid($profile, $sessionWorkItem, $trace),
273	            AiCandidateActionType::ThrottleMine => $this->scheduleMinePercent($profile, $sessionWorkItem),
274	            AiCandidateActionType::Phalanx => $this->schedulePhalanx($profile, $sessionWorkItem),
275	            AiCandidateActionType::Defend => $this->scheduleDefend($profile, $sessionWorkItem),
276	            AiCandidateActionType::Trade => $this->scheduleTrade($profile, $sessionWorkItem),
277	            AiCandidateActionType::Relocate => $this->scheduleRelocation($profile, $sessionWorkItem),
278	            AiCandidateActionType::JumpGate => $this->scheduleJumpGate($profile, $sessionWorkItem),
279	            AiCandidateActionType::DoNothing => $this->recordQuietDecision($profile, $trace),
280	        };
281	
282	        // The war fleet's own order, on a login that chose something else: a player with a war chest
283	        // keeps the shipyard busy whichever page they opened, so the surplus buys the best hull the
284	        // yard can build without waiting for the sessions the engine happens to pick the shipyard. The
285	        // fleet is asked of the planner directly rather than read from the plan above, which only
286	        // carries it when no other role on any planet wanted anything: a login is almost always
287	        // consumed by a probe, a colony ship or a wall, so the plan the schedule was handed never held
288	        // a hull and the account bought none (measured live: 160 QueueUnits orders in half an hour and
289	        // no hull above the median military hull anywhere in the cohort). It is written after the
290	        // building steps, which are priced against the balance first, and a session that decided
291	        // nothing is one with no intent to spend.
292	        $capital = $units instanceof QueueableUnit && $units->surplusSpend
293	            ? $units
294	            : $this->queueableUnitPlanner->capitalFleetOrder($profile->player_id);
295	
296	        // A player whose yard still holds an unfinished order does not click buy again: the surplus
297	        // hull is a habit, not an errand, and a login that ordered on top of an unfinished batch
298	        // buried the shipyard under identical hulls (measured live 3 Oct 2026: 425 unit orders in
299	        // half an hour against 1,057 buildings). The wall orders above are untouched: keeping a
300	        // planet alive is what the yard is for.
301	        if ($capital !== null
302	            && ! $this->shipyardsBusy($profile->player_id)
303	            && ! ($type === AiCandidateActionType::QueueUnits && $units === $capital)
304	            && $type !== AiCandidateActionType::DoNothing) {
305	            $this->scheduleUnits($profile, $sessionWorkItem, $this->clock->now()->addSeconds($economySteps * self::SECONDS_BETWEEN_PLANETS), $capital, ':capital');
306	        }
307	    }
308	
309	    /**
310	     * The shipyard arm of a login: the plan's surplus hull, or nothing while the yard already holds an
311	     * unfinished order. The hull is what the account buys when no role on any planet wanted anything --
312	     * a habit rather than an errand -- so a login that finds the yard busy leaves it alone instead of
313	     * stacking a second identical batch behind the first (ARB-001: units ordered on eight of six logins).
314	     * The wall, the cargo and the probes above keep their orders: those are the errands.
315	     */
316	    private function scheduleShipyard(AiProfile $profile, AiWorkItem $sessionWorkItem, CarbonImmutable $dueAt, ?QueueableUnit $plan): void
317	    {
318	        if ($plan instanceof QueueableUnit && $plan->surplusSpend && $this->shipyardsBusy($profile->player_id)) {
319	            return;
320	        }
321	
322	        $this->scheduleUnits($profile, $sessionWorkItem, $dueAt, $plan);
323	    }
324	
325	    /** Whether any of the player's yards holds an order the host has not finished building yet. */
326	    private function shipyardsBusy(int $playerId): bool
327	    {
328	        $planets = Planet::query()->where('user_id', $playerId)->pluck('id');
329	
330	        return UnitQueue::query()->whereIn('planet_id', $planets)->where('processed', 0)->exists();
331	    }
332	
333	    private function isCalmSave(AiCandidateActionType $type, DecisionTrace $trace): bool
334	    {
335	        return $type === AiCandidateActionType::FleetSave && $trace->perception->inboundFleets === [];
336	    }
337	
338	    /** Whether this session refills the build queues and the lab before its own objective. */
339	    private function refillsQueues(AiCandidateActionType $type, DecisionTrace $trace): bool
340	    {
341	        return $type !== AiCandidateActionType::DoNothing && $this->economyOffered($trace);
342	    }
343	
344	    /** Only what the engine offered this session, so legality and persona policy stay its own. */
345	    private function economyOffered(DecisionTrace $trace): bool
346	    {
347	        foreach ($trace->candidates as $scored) {
348	            if (in_array($scored->candidate->type, [AiCandidateActionType::Build, AiCandidateActionType::Research], true)) {
349	                return true;
350	            }
351	        }
352	
353	        return false;
354	    }
355	
356	    /**
357	     * The key the queue refill owns. Build and Research own the session's own key, so the refill is
358	     * the session's objective; every other action takes a key of its own, leaving the objective's key
359	     * to the objective.
360	     */
361	    private function economyKey(AiCandidateActionType $type): string
362	    {
363	        return match ($type) {
364	            AiCandidateActionType::Build, AiCandidateActionType::Research => '',
365	            default => ':economy',
366	        };
367	    }
368	
369	    /**
370	     * One intent per queue the planner found free and payable: a building per planet and one
371	     * technology. Legality is re-asked here rather than trusted from the decision, and the step the
372	     * planner verified travels with the intent, so the schedule and the executor name one objective.
373	     * The first step keeps the session's own key, so a retried session converges on the same work.
374	     */
375	    private function fillQueues(AiProfile $profile, AiWorkItem $sessionWorkItem, string $keyPrefix): int
376	    {
377	        $steps = $this->queueableBuildingPlanner->steps($profile->player_id);
378	        foreach ($steps as $index => $step) {
379	            [$kind, $payload] = $step instanceof QueueableResearch
380	                ? [AiWorkKind::QueueResearch, [self::PAYLOAD_RESEARCH_ID => $step->researchId]]
381	                : [AiWorkKind::BuildFirstBuilding, [self::PAYLOAD_BUILDING_ID => $step->buildingId]];
382	
383	            $this->enqueue($profile, $sessionWorkItem, $kind, [
384	                self::PAYLOAD_PLANET_ID => $step->planetId,
385	                ...$payload,
386	                self::PAYLOAD_REASON => $step->reason,
