 3	namespace Modules\AI\Support;
 4	
 5	use Carbon\Carbon;
 6	use Carbon\CarbonImmutable;
 7	use Carbon\CarbonInterface;
 8	use Illuminate\Support\Carbon as IlluminateCarbon;
 9	use Illuminate\Support\Facades\Date;
10	
11	/**
12	 * The one switch that moves game time without waiting for it.
13	 *
14	 * OGame is calculation over timestamps: production, queues, flights and the module's routines all read
15	 * "now" from Carbon (the host's `now()` and `Date::now()`, the module's `AiClock`). Freezing or moving
16	 * Carbon's test instant therefore moves the whole game at once, with no wall-clock hour in between.
17	 * Every Carbon flavour is set together because each keeps its own test instant.
18	 *
19	 * DEV TOOLING for simulation and tests: `ai:sim` steps this clock through simulated hours, the
20	 * `AI_SIM_NOW` environment variable freezes any script or tinker run at an instant, and tests use
21	 * it to stand at a known hour. Nothing in a live request path calls it.
22	 */
23	final class SimulatedTime
24	{
25	    /** Freeze every Carbon flavour at one instant and return it. */
26	    public static function freezeAt(CarbonInterface|string $instant): CarbonImmutable
27	    {
28	        $at = CarbonImmutable::parse($instant);
29	
30	        Carbon::setTestNow($at);
31	        CarbonImmutable::setTestNow($at);
32	        IlluminateCarbon::setTestNow($at);
33	        Date::setTestNow($at);
34	
35	        return $at;
36	    }
37	
38	    /** Move the frozen clock forward (negative values move it back). */
39	    public static function advance(int $seconds): CarbonImmutable
40	    {
41	        return self::freezeAt(self::now()->addSeconds($seconds));
42	    }
43	
44	    /** The instant the game currently reads, simulated or real. */
45	    public static function now(): CarbonImmutable
46	    {
47	        return CarbonImmutable::now();
48	    }
49	
50	    /** Back to the wall clock. */
51	    public static function release(): void
52	    {
53	        Carbon::setTestNow();
54	        CarbonImmutable::setTestNow();
55	        IlluminateCarbon::setTestNow();
56	        Date::setTestNow();
57	    }
58	
59	    public static function isFrozen(): bool
60	    {
61	        return CarbonImmutable::hasTestNow();
62	    }
63	
64	    /**
65	     * Freeze at the instant a process was asked to stand at: `AI_SIM_NOW=2026-10-05T12:00:00Z`.
66	     * An empty or missing variable leaves the wall clock alone.
67	     */
68	    public static function freezeFromEnvironment(): void
69	    {
70	        $instant = getenv('AI_SIM_NOW');
71	
72	        if ($instant === false || trim($instant) === '') {
73	            return;
74	        }
75	
76	        self::freezeAt(trim($instant));
77	    }
78	}

