48	function lateLoginProfile(int $playerId): AiProfile
49	{
50	    return AiProfile::create([
51	        'player_id' => $playerId,
52	        'archetype' => AiArchetype::Miner,
53	        'skill_band' => AiSkillBand::Standard,
54	        'random_seed' => 20_007,
55	        'enabled' => true,
