59	/**
60	 * The first minute of the account's own night: step into its waking day from wherever the clock is, then
61	 * forward to the minute it goes to sleep. A story about the night must not depend on the hour the suite
62	 * happens to run at.
63	 */
64	function lateLoginBed(AiProfile $profile): CarbonImmutable
65	{
66	    $planner = app(SessionPlanner::class);
67	    $instant = now()->toImmutable();
68	
69	    for ($step = 0; $step < 2880 && !$planner->isAwake($profile, $instant); $step++) {
70	        $instant = $instant->addMinute();
71	    }
72	
73	    for ($step = 0; $step < 2880 && $planner->isAwake($profile, $instant); $step++) {
74	        $instant = $instant->addMinute();
75	    }
76	
77	    return $instant;
78	}
