82	{
83	    return AiWorkItem::create([
84	        'player_id' => $playerId,
85	        'kind' => AiWorkKind::RunSession,
86	        'due_at' => now()->subMinutes($minutesDueAgo),
87	        'idempotency_key' => 'late-login:' . $minutesDueAgo . ':' . uniqid(),
88	        'state' => AiWorkState::Pending,
89	    ]);
90	}

