383	/**
384	 * Plant, drive, read back. The read-back is polled: the scenario passes the moment the expected
385	 * work appears and fails only when the wait runs out.
386	 *
387	 * @param  array<string, mixed>  $definition
388	 * @param  array<string, mixed>  $options
389	 * @return array<string, mixed>
390	 */
391	function run_scenario(string $name, array $definition, array $context, array $options): array
392	{
393	    if ($definition['writes'] && !$options['confirm']) {
394	        echo 'SCENARIO: SKIP '.$name.' — writes to the world; pass --confirm (it proves: '
395	            .$definition['proves'].")\n";
396	
397	        return ['name' => $name, 'ok' => true, 'skipped' => 'needs --confirm'];
398	    }
399	
400	    if ($definition['writes'] && count($context['players']) < 2) {
401	        echo 'SCENARIO: SKIP '.$name." — needs two enabled accounts to put a neighbour beside a target\n";
402	
403	        return ['name' => $name, 'ok' => true, 'skipped' => 'needs two accounts'];
404	    }
405	
406	    $context['before'] = CarbonImmutable::now();
407	    $context['arrival'] = $options['arrival'];
408	    $lines = [];
409	
410	    if ($definition['plant'] !== null) {
411	        [$line, $undo] = $definition['plant']($context);
412	        remember_planted($undo);
413	        $lines[] = 'planted: '.$line;
414	    }
415	
416	    $started = microtime(true);
417	    $since = CarbonImmutable::now();
418	    $tick = 0;
419	    do {
420	        $lines[] = drive_once($context, $options['workers'], ++$tick, $since);
421	        [$ok, $detail] = $definition['expect']($context);
422	        if ($ok || microtime(true) - $started >= $options['wait']) {
423	            break;
424	        }
425	        sleep($options['workers'] ? POLL_SECONDS : 1);
426	    } while (true);
427	
428	    if (!$ok) {
429	        $detail .= ' — last decisions: '.newest_decisions($context['players'], $context['before']);
430	    }
431	
432	    if ($options['cleanup']) {
433	        $lines[] = 'cleaned up: '.revert_planted().' planted row(s) reverted';
434	    }
435	
436	    printf("SCENARIO: %s %s (%.0fs)\n", $ok ? 'PASS' : 'FAIL', $name, microtime(true) - $started);
437	
438	    foreach ($lines as $line) {
439	        echo '    '.$line."\n";
440	    }
441	
442	    echo '    read-back: '.$detail."\n";
443	
444	    return ['name' => $name, 'ok' => $ok, 'detail' => $detail, 'steps' => $lines];
445	}
