447	/**
448	 * One pass of time for the situation's accounts only: host orders finish, their own fleets arrive and
449	 * the host processes the arrivals (a probe's report, a raid's loot, a recycle), the module's work falls
450	 * due, and that work runs right here, account by account, through the real ProcessAiWork. Waiting for
451	 * the cohort's workers instead read their backlog, not the code: a situation took 183 s and still timed
452	 * out while 20 accounts queued ahead of it (1 Oct 2026). --workers keeps that path, for a test of the
453	 * runtime itself.
454	 *
455	 * @param  array<string, mixed>  $context
456	 */
457	function drive_once(array $context, bool $workers, int $tick, CarbonImmutable $since): string
458	{
459	    $now = CarbonImmutable::now();
460	    $finished = finish_host_queues($context['planets'], $now);
461	    $arrived = arrive_own_fleets($context['players'], $now);
462	    $due = make_module_work_due($context['players'], $now);
463	
464	    Artisan::call('ogamex:scheduler:process-planet-queues');
465	    Artisan::call('ogamex:scheduler:process-fleet-arrivals', ['--limit' => 200]);
466	
467	    if ($workers) {
468	        Artisan::call('ai:run-due-work', ['--limit' => 40]);
469	    }
470	    $ran = $workers ? 0 : run_own_work($context['players']);
471	
472	    return sprintf('tick %d: %d order(s) finished, %d fleet(s) arrived, %d item(s) made due, %d run here, %d work item(s) done so far',
473	        $tick, $finished, $arrived, $due, $ran, engine_ran($context['players'], $since));
474	}
