476	/**
477	 * The accounts' own fleets in flight arrive now. Only theirs: a hostile fleet planted against them
478	 * keeps its arrival, because reacting before it lands is what a save situation proves.
479	 *
480	 * @param  array<int, int>  $playerIds
481	 */
482	function arrive_own_fleets(array $playerIds, CarbonImmutable $now): int
483	{
484	    return DB::table('fleet_missions')->whereIn('user_id', $playerIds)->where('processed', 0)->where('canceled', 0)
485	        ->where('time_arrival', '>', $now->timestamp)->update(['time_arrival' => $now->timestamp]);
486	}
487	
488	/**
489	 * Every due item of these accounts, through the real job, in due order. An account a cohort worker
490	 * holds right now is left for the next tick (the job retries its own lease on contention).
491	 *
492	 * @param  array<int, int>  $playerIds
493	 */
494	function run_own_work(array $playerIds): int
495	{
496	    $ran = 0;
497	    $due = DB::table('ai_work_items')->whereIn('player_id', $playerIds)
498	        ->whereIn('state', [AiWorkState::Pending->value, AiWorkState::Retry->value])
499	        ->where('due_at', '<=', CarbonImmutable::now())->orderBy('due_at')->limit(60)->pluck('id');
500	
501	    foreach ($due as $id) {
502	        try {
503	            app()->makeWith(ProcessAiWork::class, ['workItemId' => (int) $id])->handle();
504	            $ran++;
505	        } catch (Throwable $exception) {
506	            echo '    work item '.$id.' threw: '.$exception->getMessage()."\n";
507	        }
508	    }
509	
510	    return $ran;
511	}
