513	/**
514	 * Planted rows are written down before the drive starts, so a run that is killed or times out is
515	 * cleaned up by the next run instead of leaving a hostile fleet in a live universe.
516	 *
517	 * @param  list<array<int, mixed>>  $undo  [action, table, id, restored columns]
518	 */
519	function remember_planted(array $undo): void
520	{
521	    file_put_contents(planted_file(), json_encode([...read_planted(), ...$undo]));
522	}
523	
524	/** Delete planted rows and restore overwritten ones; returns how many rows it touched. */
525	function revert_planted(): int
526	{
527	    $touched = 0;
528	
529	    foreach (read_planted() as [$action, $table, $id, $columns]) {
530	        if ($table === 'fleet_missions' && $action !== 'restore') {
531	            $touched += delete_mission_tree([$id]);
532	            continue;
533	        }
534	
535	        $query = DB::table($table)->where('id', $id);
536	        $touched += $action === 'restore' ? $query->update($columns) : $query->delete();
537	    }
538	
539	    @unlink(planted_file());
540	
541	    return $touched;
542	}
