544	/**
545	 * Give the attacked or harvesting planet the ships the situation is about, and the undo that takes them
546	 * back. A fresh cohort account owns no ships, so a situation that only planted the threat or the debris
547	 * asked it to act with nothing: not saving a fleet it does not have is correct play, and the proof read
548	 * as a failure for a reason that was not the rule's.
549	 *
550	 * @return array{0: string, 1: array{0: string, 1: string, 2: int, 3: array<string, int>}}
551	 */
552	function lend_ships(int $planetId, string $ship, int $amount): array
553	{
554	    $held = (int) DB::table('planets')->where('id', $planetId)->value($ship);
555	    DB::table('planets')->where('id', $planetId)->update([$ship => $held + $amount]);
556	
557	    return ["{$amount} {$ship} on planet {$planetId}", ['restore', 'planets', $planetId, [$ship => $held]]];
558	}
