560	/**
561	 * Delete fleet missions and every mission that hangs off them. The engine adds a return mission with
562	 * `parent_id` set once it processes a planted fleet, and the foreign key refuses to delete the parent
563	 * first: that error aborted every revert and left the planted rows in the cohort (88 error lines in
564	 * one evening of runs).
565	 *
566	 * @param list<int> $ids
567	 */
568	function delete_mission_tree(array $ids): int
569	{
570	    $children = DB::table('fleet_missions')->whereIn('parent_id', $ids)->pluck('id')->map(fn ($id): int => (int) $id)->all();
571	    $deleted = $children === [] ? 0 : delete_mission_tree($children);
572	
573	    return $deleted + DB::table('fleet_missions')->whereIn('id', $ids)->delete();
574	}
