576	/** @return list<array{0: string, 1: string, 2: int, 3: array<string, mixed>}> */
577	function read_planted(): array
578	{
579	    $rows = is_file(planted_file()) ? json_decode((string) file_get_contents(planted_file()), true) : [];
580	
581	    return array_map(static fn (array $row): array => [$row[0], $row[1], (int) $row[2], (array) ($row[3] ?? [])], is_array($rows) ? $rows : []);
582	}
