589	/**
590	 * Work the engine actually finished since the run started: the number that says whether driving it
591	 * did anything, which `Artisan::output()` cannot (the command prints nothing when it is happy).
592	 *
593	 * @param  array<int, int>  $playerIds
594	 */
595	function engine_ran(array $playerIds, CarbonImmutable $since): int
596	{
597	    return DB::table('ai_work_items')
598	        ->whereIn('player_id', $playerIds)
599	        ->whereIn('state', [AiWorkState::Completed->value, AiWorkState::Failed->value])
600	        ->where('updated_at', '>=', $since)
601	        ->count();
