604	/**
605	 * Hand every started host order the completion time "now", the same move
606	 * `fast-forward-cohort-queues.php` makes, so the apply step has something to consume.
607	 *
608	 * @param  array<int, int>  $planetIds
609	 */
610	function finish_host_queues(array $planetIds, CarbonImmutable $now): int
611	{
612	    // Per-table scope, because the host's queues are not shaped alike: only the building and research
613	    // queues carry `canceled`, and only they use `building` to say an order has actually started.
614	    $live = [
615	        'building_queues' => static fn ($query) => $query->where('canceled', 0)->where('building', 1),
616	        'research_queues' => static fn ($query) => $query->where('canceled', 0)->where('building', 1),
617	        'unit_queues' => static fn ($query) => $query,
618	    ];
619	
620	    $moved = 0;
621	
622	    foreach ($live as $table => $scope) {
623	        $moved += $scope(DB::table($table)->whereIn('planet_id', $planetIds)->where('processed', 0))
624	            ->where(static function ($query) use ($now): void {
625	                $query->where('time_end', '>', $now->timestamp)->orWhere('time_start', '>', $now->timestamp);
626	            })
627	            ->update(['time_start' => $now->timestamp, 'time_end' => $now->timestamp]);
628	    }
629	
630	    return $moved;
631	}
