633	/**
634	 * The module's own clock: work that is due later is due now, so a scenario does not wait for a
635	 * schedule that was written for a real day.
636	 *
637	 * @param  array<int, int>  $playerIds
638	 */
639	function make_module_work_due(array $playerIds, CarbonImmutable $now): int
640	{
641	    $states = [AiWorkState::Pending->value, AiWorkState::Retry->value];
642	
643	    $work = DB::table('ai_work_items')
644	        ->whereIn('player_id', $playerIds)
645	        ->whereIn('state', $states)
646	        ->where('due_at', '>', $now)
647	        ->update(['due_at' => $now]);
648	
649	    return $work + DB::table('ai_schedules')
650	        ->whereIn('player_id', $playerIds)
651	        ->where('next_due_at', '>', $now)
652	        ->update(['next_due_at' => $now]);
653	}
