688	/**
689	 * Why the decision engine refused to act, when it refused: the reason a scenario like
690	 * `lootable-neighbour` fails is usually a gate in the planner, not a missing account.
691	 *
692	 * @param  array<int, int>  $playerIds
693	 * @return array<int, string>
694	 */
695	function refusal_reasons(array $playerIds, CarbonImmutable $since): array
696	{
697	    $reasons = [];
698	
699	    foreach (DB::table('ai_decision_traces')->whereIn('player_id', $playerIds)->where('created_at', '>=', $since)->get(['selected_reason', 'score_components']) as $trace) {
700	        $components = json_decode((string) $trace->score_components, true);
701	        $refusals = is_array($components) ? ($components['rejections'] ?? []) : [];
702	
703	        foreach (array_keys((array) $refusals) as $reason) {
704	            $reasons[(string) $reason] = true;
705	        }
706	
707	        if ($trace->selected_reason !== null && str_contains((string) $trace->selected_reason, 'not_permitted')) {
708	            $reasons[(string) $trace->selected_reason] = true;
709	        }
710	    }
711	
712	    return array_keys($reasons);
713	}
