/**
 * An account whose own clock puts the test's frozen instant inside its waking window.
 *
 * A login is taken inside the account's waking window and nowhere else (AUTH_UPTIME): an account that is
 * asleep is not logged in at all, which is a story of its own (`LateLoginNightRestTest`). The waking window
 * is the profile's local day, so the story stands in a timezone where the test's midnight is the account's
 * afternoon instead of moving the host clock, which would age every fixture the test case created.
 */
function sessionAwakeProfile(int $playerId): AiProfile
{
    return AiProfile::create([
        'player_id' => $playerId,
        'archetype' => AiArchetype::Fleeter,
        'skill_band' => AiSkillBand::Standard,
        'random_seed' => 42,
        'settings' => ['timezone' => 'Australia/Brisbane'],
    ]);
}", "old_string": "    expect(Planet::query()->findOrFail($colony->id)->metal_mine)->toBe(1);
});", "path": "tests/Feature/ProcessAiSessionTest.php"}

